const securityHeaders = {
  "Content-Security-Policy": "default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self'; img-src 'self' data:; connect-src 'self'; frame-src https://britbrae08.github.io; frame-ancestors 'none'; base-uri 'self'; form-action 'self' mailto:",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Cross-Origin-Opener-Policy": "same-origin",
};
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, HEAD" } });
    }
    const asset = assets.get(url.pathname);
    if (!asset) {
      return new Response("Not Found", { status: 404, headers: securityHeaders });
    }
    const headers = new Headers(securityHeaders);
    headers.set("Content-Type", asset.contentType);
    headers.set("Cache-Control", asset.cacheControl);
    const body = asset.encoding === "base64" ? Uint8Array.from(atob(asset.body), (char) => char.charCodeAt(0)) : asset.body;
    return new Response(request.method === "HEAD" ? null : body, { status: 200, headers });
  },
};
